import{_ as l,o as i,c as t,a2 as e}from"./chunks/framework.7R1OEGYz.js";const c=JSON.parse('{"title":"인력관리시스템 요구사항분석서","description":"","frontmatter":{},"headers":[],"relativePath":"requirements-analysis.md","filePath":"requirements-analysis.md"}'),r={name:"requirements-analysis.md"};function d(h,a,o,n,u,s){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="인력관리시스템-요구사항분석서" tabindex="-1">인력관리시스템 요구사항분석서 <a class="header-anchor" href="#인력관리시스템-요구사항분석서" aria-label="Permalink to &quot;인력관리시스템 요구사항분석서&quot;">​</a></h1><p>작성일: 2026-06-25</p><h2 id="_1-개요" tabindex="-1">1. 개요 <a class="header-anchor" href="#_1-개요" aria-label="Permalink to &quot;1. 개요&quot;">​</a></h2><p>본 시스템은 경비원, 미화원, 파견직 등 현장 근무자의 인사 정보, 근무지 배정, 출퇴근, 안전교육, 현장점검, 특이사항 보고를 통합 관리하기 위한 인력관리시스템이다.</p><p>관리자는 웹 화면에서 직원과 현장을 관리하고, 근무 현황과 교육 이수 현황을 확인하며, 필요한 자료를 조회하거나 엑셀로 내려받을 수 있어야 한다. 근무자는 모바일 화면에서 본인의 근무지와 일정, 출퇴근, 교육, 순찰 또는 청소구역 점검, 특이사항 보고를 간편하게 처리할 수 있어야 한다.</p><h2 id="_2-이용자" tabindex="-1">2. 이용자 <a class="header-anchor" href="#_2-이용자" aria-label="Permalink to &quot;2. 이용자&quot;">​</a></h2><table tabindex="0"><thead><tr><th>이용자</th><th>설명</th></tr></thead><tbody><tr><td>관리자</td><td>직원, 근무지, 배정, 교육, 점검, 보고서, 시스템 설정을 관리하는 사용자</td></tr><tr><td>현장 근무자</td><td>모바일 화면으로 출퇴근, 교육 이수, 점검, 특이사항 보고를 수행하는 사용자</td></tr></tbody></table><h2 id="_3-업무-범위" tabindex="-1">3. 업무 범위 <a class="header-anchor" href="#_3-업무-범위" aria-label="Permalink to &quot;3. 업무 범위&quot;">​</a></h2><p>시스템은 다음 업무를 지원한다.</p><table tabindex="0"><thead><tr><th>구분</th><th>주요 업무</th></tr></thead><tbody><tr><td>직원관리</td><td>직원 등록, 수정, 퇴직 여부 관리, 직원 목록 조회</td></tr><tr><td>근무지관리</td><td>근무지 등록, 수정, 주소와 GPS 정보 관리</td></tr><tr><td>근무배정</td><td>직원별 근무지와 근무기간 배정, 중복 배정 방지</td></tr><tr><td>출퇴근관리</td><td>근무자의 출근/퇴근 처리, 현재 출근 현황 확인</td></tr><tr><td>안전교육</td><td>교육자료 등록, 직원별 이수 현황 확인, 미이수자 알림 발송</td></tr><tr><td>현장점검</td><td>점검 현장 등록, QR/NFC 기반 점검 기록, 점검 이력 확인</td></tr><tr><td>특이사항</td><td>근무 중 발생한 특이사항 작성, 위치와 사진 포함 보고, 관리자 확인</td></tr><tr><td>리포트</td><td>근태내역과 교육이수자료 조회 및 엑셀 다운로드</td></tr><tr><td>시스템관리</td><td>로그 확인, 시스템 설정 관리</td></tr></tbody></table><h2 id="_4-관리자-요구사항" tabindex="-1">4. 관리자 요구사항 <a class="header-anchor" href="#_4-관리자-요구사항" aria-label="Permalink to &quot;4. 관리자 요구사항&quot;">​</a></h2><h3 id="_4-1-대시보드" tabindex="-1">4.1 대시보드 <a class="header-anchor" href="#_4-1-대시보드" aria-label="Permalink to &quot;4.1 대시보드&quot;">​</a></h3><ul><li>관리자는 전체 직원 수, 현재 출근 인원, 교육 미이수 인원을 한 화면에서 확인할 수 있어야 한다.</li><li>관리자는 일별 출근율과 안전교육 이수율 추이를 차트로 확인할 수 있어야 한다.</li><li>관리자는 현장별 배정 인원과 실시간 출근 현황을 확인할 수 있어야 한다.</li></ul><h3 id="_4-2-직원-및-근무지-관리" tabindex="-1">4.2 직원 및 근무지 관리 <a class="header-anchor" href="#_4-2-직원-및-근무지-관리" aria-label="Permalink to &quot;4.2 직원 및 근무지 관리&quot;">​</a></h3><ul><li>관리자는 직원의 이름, 연락처, 직무 구분을 등록하고 수정할 수 있어야 한다.</li><li>관리자는 퇴직한 직원을 별도로 표시하거나 관리할 수 있어야 한다.</li><li>관리자는 근무지의 이름, 주소, GPS 위치, 출근 인정 반경을 등록하고 수정할 수 있어야 한다.</li><li>관리자는 직원별 근무지와 근무기간을 배정할 수 있어야 한다.</li><li>시스템은 같은 직원에게 겹치는 기간의 근무배정이 등록되지 않도록 해야 한다.</li></ul><h3 id="_4-3-안전교육-관리" tabindex="-1">4.3 안전교육 관리 <a class="header-anchor" href="#_4-3-안전교육-관리" aria-label="Permalink to &quot;4.3 안전교육 관리&quot;">​</a></h3><ul><li>관리자는 안전교육 자료의 제목과 영상 링크를 등록하고 수정할 수 있어야 한다.</li><li>관리자는 직원별 교육 이수 여부와 미이수 건수를 확인할 수 있어야 한다.</li><li>관리자는 교육을 이수하지 않은 직원에게 교육 알림을 발송할 수 있어야 한다.</li><li>관리자는 자동으로 발송된 알림의 처리 결과를 조회할 수 있어야 한다.</li></ul><h3 id="_4-4-현장점검-관리" tabindex="-1">4.4 현장점검 관리 <a class="header-anchor" href="#_4-4-현장점검-관리" aria-label="Permalink to &quot;4.4 현장점검 관리&quot;">​</a></h3><ul><li>관리자는 점검 대상 현장을 등록하고 근무지와 연결할 수 있어야 한다.</li><li>관리자는 현장별 QR 코드 또는 NFC 주소를 생성하여 현장 점검에 사용할 수 있어야 한다.</li><li>관리자는 근무자가 수행한 점검 기록을 근무지별로 조회할 수 있어야 한다.</li><li>관리자는 근무자가 보고한 특이사항의 내용, 보고자, 근무지, 보고일시, 위치, 사진을 확인할 수 있어야 한다.</li></ul><h3 id="_4-5-리포트-출력" tabindex="-1">4.5 리포트 출력 <a class="header-anchor" href="#_4-5-리포트-출력" aria-label="Permalink to &quot;4.5 리포트 출력&quot;">​</a></h3><ul><li>관리자는 직원 이름과 연도를 기준으로 근태내역을 조회할 수 있어야 한다.</li><li>관리자는 연도별 교육이수자료를 조회할 수 있어야 한다.</li><li>관리자는 조회한 근태내역과 교육이수자료를 엑셀 파일로 내려받을 수 있어야 한다.</li></ul><h3 id="_4-6-시스템-관리" tabindex="-1">4.6 시스템 관리 <a class="header-anchor" href="#_4-6-시스템-관리" aria-label="Permalink to &quot;4.6 시스템 관리&quot;">​</a></h3><ul><li>관리자는 근무자 로그인 및 주요 처리 로그를 확인할 수 있어야 한다.</li><li>관리자는 시스템 운영에 필요한 설정값을 등록하고 수정할 수 있어야 한다.</li></ul><h2 id="_5-현장-근무자-요구사항" tabindex="-1">5. 현장 근무자 요구사항 <a class="header-anchor" href="#_5-현장-근무자-요구사항" aria-label="Permalink to &quot;5. 현장 근무자 요구사항&quot;">​</a></h2><h3 id="_5-1-로그인" tabindex="-1">5.1 로그인 <a class="header-anchor" href="#_5-1-로그인" aria-label="Permalink to &quot;5.1 로그인&quot;">​</a></h3><ul><li>근무자는 이름과 연락처로 로그인할 수 있어야 한다.</li><li>퇴직 처리된 직원은 근무자 화면을 사용할 수 없어야 한다.</li></ul><h3 id="_5-2-메인-화면" tabindex="-1">5.2 메인 화면 <a class="header-anchor" href="#_5-2-메인-화면" aria-label="Permalink to &quot;5.2 메인 화면&quot;">​</a></h3><ul><li>근무자는 오늘 배정된 근무지를 확인할 수 있어야 한다.</li><li>근무자는 출근, 순찰 또는 청소구역 점검, 특이사항, 개인프로필 메뉴로 이동할 수 있어야 한다.</li><li>근무지 배정이 없는 경우 시스템은 관리자에게 배정을 요청하라는 안내를 제공해야 한다.</li></ul><h3 id="_5-3-출퇴근" tabindex="-1">5.3 출퇴근 <a class="header-anchor" href="#_5-3-출퇴근" aria-label="Permalink to &quot;5.3 출퇴근&quot;">​</a></h3><ul><li>근무자는 배정된 근무지 반경 안에서 출근할 수 있어야 한다.</li><li>근무지 반경 밖에서는 출근할 수 없으며, 사유를 안내받아야 한다.</li><li>근무자는 출근 기록이 있는 경우 퇴근할 수 있어야 한다.</li><li>근무자는 본인의 출근 상태와 오늘의 근무 정보를 확인할 수 있어야 한다.</li></ul><h3 id="_5-4-안전교육" tabindex="-1">5.4 안전교육 <a class="header-anchor" href="#_5-4-안전교육" aria-label="Permalink to &quot;5.4 안전교육&quot;">​</a></h3><ul><li>근무자는 모바일 화면에서 안전교육 자료를 확인하고 영상을 시청할 수 있어야 한다.</li><li>근무자는 교육 이수 처리를 할 수 있어야 한다.</li><li>시스템은 직원별 교육 이수 상태를 저장하여 관리자가 확인할 수 있게 해야 한다.</li></ul><h3 id="_5-5-현장점검" tabindex="-1">5.5 현장점검 <a class="header-anchor" href="#_5-5-현장점검" aria-label="Permalink to &quot;5.5 현장점검&quot;">​</a></h3><ul><li>근무자는 QR 코드 또는 NFC 태그를 이용하여 현장점검을 기록할 수 있어야 한다.</li><li>경비원은 순찰 기록을, 미화원은 청소구역 점검 기록을 남길 수 있어야 한다.</li><li>점검 기록에는 근무자, 근무지, 현장, 점검 시간이 포함되어야 한다.</li></ul><h3 id="_5-6-특이사항-보고" tabindex="-1">5.6 특이사항 보고 <a class="header-anchor" href="#_5-6-특이사항-보고" aria-label="Permalink to &quot;5.6 특이사항 보고&quot;">​</a></h3><ul><li>근무자는 근무 중 발견한 특이사항을 작성하여 관리자에게 보고할 수 있어야 한다.</li><li>근무자는 음성 입력과 사진 촬영을 활용하여 보고 내용을 작성할 수 있어야 한다.</li><li>시스템은 가능한 경우 보고 당시의 위치 정보를 함께 기록해야 한다.</li></ul><h3 id="_5-7-개인프로필" tabindex="-1">5.7 개인프로필 <a class="header-anchor" href="#_5-7-개인프로필" aria-label="Permalink to &quot;5.7 개인프로필&quot;">​</a></h3><ul><li>근무자는 본인의 근무스케줄을 확인할 수 있어야 한다.</li><li>근무자는 월별 출근일수와 근무시간을 확인할 수 있어야 한다.</li><li>근무자는 글자 크기를 조절할 수 있어야 한다.</li></ul><h2 id="_6-알림-요구사항" tabindex="-1">6. 알림 요구사항 <a class="header-anchor" href="#_6-알림-요구사항" aria-label="Permalink to &quot;6. 알림 요구사항&quot;">​</a></h2><ul><li>시스템은 근무자의 모바일 기기에 푸시 알림 수신 정보를 등록할 수 있어야 한다.</li><li>관리자는 안전교육 미이수자에게 교육 독려 알림을 보낼 수 있어야 한다.</li><li>시스템은 알림 발송 성공, 실패, 미수신 대상을 관리자가 확인할 수 있도록 제공해야 한다.</li></ul><h2 id="_7-보안-및-접근-요구사항" tabindex="-1">7. 보안 및 접근 요구사항 <a class="header-anchor" href="#_7-보안-및-접근-요구사항" aria-label="Permalink to &quot;7. 보안 및 접근 요구사항&quot;">​</a></h2><ul><li>관리자 기능은 일반 근무자와 분리되어야 한다.</li><li>근무자는 본인에게 배정된 정보와 본인의 처리 내역을 중심으로 조회할 수 있어야 한다.</li><li>직원 개인정보와 인증 관련 정보는 외부에 노출되지 않도록 관리되어야 한다.</li></ul><h2 id="_8-사용성-요구사항" tabindex="-1">8. 사용성 요구사항 <a class="header-anchor" href="#_8-사용성-요구사항" aria-label="Permalink to &quot;8. 사용성 요구사항&quot;">​</a></h2><ul><li>관리자 화면은 PC와 모바일 화면에서 모두 메뉴를 이용할 수 있어야 한다.</li><li>근무자 화면은 모바일 사용을 기준으로 큰 버튼과 읽기 쉬운 글자를 제공해야 한다.</li><li>근무자의 출퇴근 및 점검 기능은 위치 권한 허용을 전제로 한다.</li><li>푸시 알림 기능은 근무자가 지원 브라우저에서 알림 권한을 허용한 경우 사용할 수 있다.</li></ul>',44)])])}const b=l(r,[["render",d]]);export{c as __pageData,b as default};
